mapper.select:
SELECT *
FROM matchmaking_ticket
WHERE user_id = #{userId}
  AND script_id = #{scriptId}
  AND status = 'WAITING'
LIMIT 1

SELECT *
FROM matchmaking_ticket
WHERE user_id = #{userId}
  AND script_id = #{scriptId}
ORDER BY id DESC
LIMIT 1

SELECT *
FROM matchmaking_ticket
WHERE script_id = #{scriptId}
  AND status = 'WAITING'
ORDER BY create_time ASC, id ASC
LIMIT #{limit}

mapper.update:
UPDATE matchmaking_ticket
SET status          = #{status},
    matched_room_id = #{matchedRoomId}
WHERE id = #{id}

UPDATE matchmaking_ticket
SET status          = 'MATCHED',
    matched_room_id = #{roomId}
WHERE id = #{id}
  AND status = 'WAITING'
